+fn circular_vault_inside_cuts_full_ladders_to_the_existing_ring_floors() {
+    for (start, entry, radii) in [
+        (None, "plunge", [5.0, 3.0, 1.0]),
+        (Some("outside"), "plunge", [5.0, 3.0, 1.0]),
